function acDB(){if(!DB.academias)DB.academias=[];if(!DB.alumnos)DB.alumnos=[];if(!DB.acadPagos)DB.acadPagos=[];if(!DB.acadIngresos)DB.acadIngresos=[];return DB.academias}
const acad=id=>acDB().find(a=>a.id===id);
